if(StarMgr.getFlagStars()) {
    core.debug("Stars are visible");
} else {
    StarMgr.setFlagStars(true);
}

// Hide all stars
StarMgr.setFlagStars(false);

// Show all stars
StarMgr.setFlagStars(true);

// Toggle stars
var current = StarMgr.getFlagStars();
StarMgr.setFlagStars(!current);

if(StarMgr.getFlagLabels()) {
    core.debug("Star labels are visible");
}

// Show star names
StarMgr.setFlagLabels(true);

// Hide star names
StarMgr.setFlagLabels(false);

// Show only bright stars
StarMgr.setLabelsAmount(2.0);

// Show many star labels
StarMgr.setLabelsAmount(7.0);

if(StarMgr.getFlagSciNames()) {
    core.debug("Scientific star names are shown");
}

// Show scientific names (Bayer/Flamsteed)
StarMgr.setFlagSciNames(true);

// Show only common names
StarMgr.setFlagSciNames(false);

if(StarMgr.getFlagAdditionalNames()) {
    core.debug("Additional star names are shown");
}

// Show all star name aliases
StarMgr.setFlagAdditionalNames(true);

// Show only primary names
StarMgr.setFlagAdditionalNames(false);

if(StarMgr.getDesignationUsage()) {
    core.debug("Catalog designations are shown instead of common names");
}

// Use HIP numbers for labels
StarMgr.setDesignationUsage(true);

// Use common names
StarMgr.setDesignationUsage(false);

if(StarMgr.getFlagDblStarsDesignation()) {
    core.debug("Double star designations are shown");
}

// Show double star component designations
StarMgr.setFlagDblStarsDesignation(true);

// Hide component designations
StarMgr.setFlagDblStarsDesignation(false);

if(StarMgr.getFlagVarStarsDesignation()) {
    core.debug("Variable star designations are shown");
}

// Show variable star names
StarMgr.setFlagVarStarsDesignation(true);

// Hide variable star designations
StarMgr.setFlagVarStarsDesignation(false);

if(StarMgr.getFlagHIPDesignation()) {
    core.debug("HIP numbers are shown");
}

// Show HIP numbers
StarMgr.setFlagHIPDesignation(true);

// Hide HIP numbers
StarMgr.setFlagHIPDesignation(false);

// Show fainter stars
StarMgr.increaseStarsMagnitudeLimit();

// Repeat to show even fainter stars
for(var i=0; i<5; i++) {
    StarMgr.increaseStarsMagnitudeLimit();
    core.wait(0.5);
}

var sirius = StarMgr.searchHP(32349);
if(sirius) {
    core.debug("Found Sirius");
    core.moveToObject(sirius.getEnglishName(), 2);
}

var star = StarMgr.searchGaia(1679274403719601152);
if(star) {
    core.debug("Found Gaia star");
}

var star = StarMgr.searchByID("HIP 32349");
star = StarMgr.searchByID("SAO 151881");
star = StarMgr.searchByID("HD 48915");

var sirius = StarMgr.searchHP(32349);
if(sirius) {
    var name = StarMgr.getCommonEnglishName(32349);
    core.debug("Sirius common name: " + name);
}

var culturalNames = StarMgr.getCulturalNames(32349);
for(var i=0; i<culturalNames.length; i++) {
    core.debug("Native: " + culturalNames[i].native);
    core.debug("Pronounce: " + culturalNames[i].pronounce);
}

var star = StarMgr.searchHP(32349);
var specIndex = star.getSpInt();
var specType = StarMgr.convertToSpectralType(specIndex);
core.debug("Spectral type: " + specType);

var doubleStars = StarMgr.getHipparcosDoubleStars();
for(var i=0; i<doubleStars.length; i++) {
    var star = doubleStars[i].first;
    var sep = doubleStars[i].second;
    core.debug(star.getEnglishName() + " separation: " + sep + " arcsec");
}

var variables = StarMgr.getHipparcosVariableStars();
for(var i=0; i<variables.length; i++) {
    var star = variables[i].first;
    var period = variables[i].second;
    core.debug(star.getEnglishName() + " period: " + period + " days");
}

var cepheids = StarMgr.getHipparcosClassicalCepheidsTypeStars();
if(cepheids.length > 0) {
    core.debug("First Cepheid: " + cepheids[0].first.getEnglishName());
}

var carbonStars = StarMgr.getHipparcosCarbonStars();
for(var i=0; i<carbonStars.length; i++) {
    core.debug(carbonStars[i].getEnglishName() + " is a carbon star");
}

var highPM = StarMgr.getHipparcosHighPMStars();
core.debug("High proper motion stars: " + highPM.length);
for(var i=0; i<Math.min(5, highPM.length); i++) {
    core.debug(highPM[i].first.getEnglishName() + " velocity: " + highPM[i].second + " arcsec/year");
}

var catalogs = StarMgr.getCatalogsDescription();
for(var i=0; i<catalogs.length; i++) {
    core.debug("Catalog " + i + ": " + JSON.stringify(catalogs[i]));
}

var orbit = StarMgr.getBinaryOrbitData(95947);
if(orbit.hip) {
    core.debug("Period: " + orbit.binary_period + " days");
    core.debug("Eccentricity: " + orbit.eccentricity);
    core.debug("Primary mass: " + orbit.primary_mass + " M☉");
}
